// Raw six-language source of the Never Have I Ever catalogue.
// One card per line, always in the same order: sk|en|de|es|fr|pt
// Every line describes one single real-life situation, so the six columns are
// natural formulations of the same statement rather than literal translations.

const BLOCKS: string[] = [];

function block(lines: string) {
  BLOCKS.push(lines);
}

export function getNeverHaveIEverSourceLines(): string[] {
  return BLOCKS.join("\n")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}


